def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    prev_bids = []
    bob_prev_bid = None
    pressure_count = 0
    rich_alive = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) > 0:
            rich_alive += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 50.0:
                pressure_count += 1
        if prev.get('bid') is not None and opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
            if bob_prev_bid is None or float(prev.get('bid')) > bob_prev_bid:
                bob_prev_bid = float(prev.get('bid'))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    anchor = bob_prev_bid if bob_prev_bid is not None else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency == 3:
        bid = max(63.0, anchor + 2.5)
    elif urgency == 2:
        bid = max(52.0 + 10.0 * scarcity, anchor - 1.0)
    else:
        if supply >= 22:
            bid = 24.0 if anchor >= 60.0 else 31.0
        elif supply >= 19:
            bid = 34.0 if anchor >= 60.0 else 41.0
        else:
            bid = 43.0 if anchor >= 60.0 else 49.0

    if pressure_count >= 2:
        bid += 4.0
    if rich_alive <= 1:
        bid -= 5.0

    if no_water_days >= 2:
        bid = max(bid, 66.0)
    elif no_water_days >= 1 and hp <= 5:
        bid = max(bid, 58.0)

    reserve_floor = 35.0 if hp > 4 else 10.0
    max_affordable = max(0.0, budget - reserve_floor)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        # If alone, bid modestly to save budget
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Use only yesterday's previous_trace for immediate reaction
    prev_bids = []
    prev_hp = []
    for oid, o in alive:
        pt = o.get('previous_trace', {})
        if pt and pt.get('bid') is not None:
            prev_bids.append(float(pt['bid']))
        prev_hp.append(float(o.get('hp', 0)))

    # Estimate who is the main threat: highest previous bid
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine our urgency
    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))

    # If we are low HP, prioritize survival; otherwise, match/just-under pressure.
    # Alex likely continues high bids; Eric likely stays low; others likely 0.
    target = 0.0

    # Pressure banding
    if highest_prev_bid >= DAILY_SALARY * 0.75:
        # Alex is pressuring hard: bid near but not equal to reduce chance of losing all water
        if hp <= 2.5:
            target = DAILY_SALARY * 0.95
        elif hp <= 4.0:
            target = max(highest_prev_bid * 0.9, DAILY_SALARY * 0.7)
        else:
            target = max(highest_prev_bid * 0.85, DAILY_SALARY * 0.6)
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        # Moderate pressure: bid enough to be competitive
        if hp <= 2.5:
            target = DAILY_SALARY * 0.9
        else:
            target = max(highest_prev_bid * 0.75, DAILY_SALARY * 0.5)
    else:
        # Low pressure overall: conserve
        if hp <= 2.5:
            target = DAILY_SALARY * 0.85
        else:
            target = DAILY_SALARY * 0.45

    # Convert target to feasible bid given our budget
    bid = max(0.0, min(budget, float(target)))

    # If supply is low, competition for limited water increases: slightly increase bid
    # (supply is between 15 and 25)
    if supply <= (MIN_SUPPLY + 1.0):
        bid = min(budget, bid * 1.15)
    elif supply >= (MAX_SUPPLY - 1.0):
        bid = bid * 0.95

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
    max_prev_bid = max(prev_bids) if prev_bids else 0.0
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']
    # Urgency based on health and water deprivation
    if hp <= 2 or no_water >= 2:
        target_bid = min(budget, max_prev_bid * 0.95 + 1.0)
    elif hp <= 4:
        target_bid = min(budget, max_prev_bid * 0.8 + 2.0)
    else:
        target_bid = min(budget, max(DAILY_SALARY * 0.5, max_prev_bid * 0.65))
    # Ensure we don't exceed budget
    return min(budget, target_bid)
